// Parse FIS results HTML
const html = $input.first().json.body;

// Extract window.fisProperties metadata
const metadataMatch = html.match(/window\.fisProperties\s*=\s*({[^}]+})/s);
let metadata = {};
if (metadataMatch) {
  try {
    metadata = JSON.parse(metadataMatch[1]);
  } catch (e) {
    metadata = { error: 'Failed to parse metadata' };
  }
}

// Simple regex extraction for results table
// Format: Rank, Name, Nation, Run1, Run2, Total, Diff
const results = [];
const rowPattern = /<tr[^>]*>\s*<td[^>]*>\s*(\d+|DNF|DNS|DSQ)\s*<\/td>.*?<td[^>]*>.*?<a[^>]*>([^<]+)<\/a>.*?<td[^>]*>\s*(\w{3})\s*<\/td>.*?<td[^>]*>\s*([\d:.]+)\s*<\/td>.*?<td[^>]*>\s*([\d:.]+)\s*<\/td>.*?<td[^>]*>\s*([\d:.]+)\s*<\/td>.*?<td[^>]*>\s*([+\d.]+|—)\s*<\/td>/gs;

let match;
while ((match = rowPattern.exec(html)) !== null) {
  results.push({
    rank: match[1],
    name: match[2].trim(),
    nation: match[3],
    run1: match[4],
    run2: match[5],
    total: match[6],
    diff: match[7]
  });
}

// Generate content hash for change detection
const crypto = require('crypto');
const contentHash = crypto.createHash('md5').update(JSON.stringify(results)).digest('hex');

return {
  metadata,
  results,
  contentHash,
  resultCount: results.length,
  winner: results[0] || null,
  podium: results.slice(0, 3),
  fetchedAt: new Date().toISOString()
};

