// Parse Claude response and extract article
const response = $input.first().json;
const content = response.content[0].text;

// Parse the JSON from Claude's response
let article;
try {
  // Find JSON in response (Claude sometimes adds explanation text)
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    article = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found in response');
  }
} catch (e) {
  return {
    error: 'Failed to parse article JSON',
    rawContent: content
  };
}

// Legal blocklist check
const blocklist = [
  'olympic', 'olympics', 'olympiad', 'olimpico', 'olimpiade',
  'paralympic', 'paralimpico',
  'milano cortina 2026', 'cortina 2026', 'milano 2026',
  'winter games 2026', 'games of 2026', 'the games',
  'going for gold', 'medal hopes',
  'team usa', 'team italy', 'team canada', 'team france', 'team germany'
];

const fullText = (article.headline + ' ' + article.excerpt + ' ' + article.content).toLowerCase();
const violations = blocklist.filter(term => fullText.includes(term));

if (violations.length > 0) {
  return {
    error: 'LEGAL_VIOLATION',
    violations,
    article
  };
}

// Generate slug from headline
const slug = article.headline
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  .substring(0, 80);

return {
  slug,
  headline: article.headline,
  excerpt: article.excerpt,
  content: article.content,
  category: 'alpine-skiing',
  sport_code: 'ALP',
  status: 'draft',
  legalCheck: 'passed',
  generatedAt: new Date().toISOString()
};
